CREATE TYPE "QuestionStatus" AS ENUM ('CONFIRMED', 'NEEDS_REVIEW');
CREATE TYPE "ExamMode" AS ENUM ('PRACTICE', 'EXAM');
CREATE TYPE "ImportStatus" AS ENUM ('PREVIEWED', 'IMPORTED');
CREATE TABLE "AdminUser" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Subject" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Subject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Chapter" ("id" TEXT NOT NULL, "subjectId" TEXT NOT NULL, "name" TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Chapter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Question" ("id" TEXT NOT NULL, "chapterId" TEXT NOT NULL, "content" TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, "status" "QuestionStatus" NOT NULL DEFAULT 'NEEDS_REVIEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Question_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Choice" ("id" TEXT NOT NULL, "questionId" TEXT NOT NULL, "content" TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, "isCorrect" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Choice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExamSet" ("id" TEXT NOT NULL, "subjectId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "mode" "ExamMode" NOT NULL DEFAULT 'EXAM', "shuffleQuestions" BOOLEAN NOT NULL DEFAULT false, "shuffleChoices" BOOLEAN NOT NULL DEFAULT false, "showAnswers" BOOLEAN NOT NULL DEFAULT false, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ExamSet_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExamSetQuestion" ("examSetId" TEXT NOT NULL, "questionId" TEXT NOT NULL, "order" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "ExamSetQuestion_pkey" PRIMARY KEY ("examSetId", "questionId"));
CREATE TABLE "ImportBatch" ("id" TEXT NOT NULL, "fileName" TEXT NOT NULL, "status" "ImportStatus" NOT NULL DEFAULT 'PREVIEWED', "questionCount" INTEGER NOT NULL DEFAULT 0, "warningCount" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ImportBatch_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");
CREATE UNIQUE INDEX "Subject_name_key" ON "Subject"("name");
CREATE INDEX "Chapter_subjectId_order_idx" ON "Chapter"("subjectId", "order");
CREATE UNIQUE INDEX "Chapter_subjectId_name_key" ON "Chapter"("subjectId", "name");
CREATE INDEX "Question_chapterId_order_idx" ON "Question"("chapterId", "order");
CREATE INDEX "Question_status_idx" ON "Question"("status");
CREATE INDEX "Choice_questionId_order_idx" ON "Choice"("questionId", "order");
CREATE INDEX "ExamSet_subjectId_active_idx" ON "ExamSet"("subjectId", "active");
CREATE INDEX "ExamSetQuestion_examSetId_order_idx" ON "ExamSetQuestion"("examSetId", "order");
ALTER TABLE "Chapter" ADD CONSTRAINT "Chapter_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Question" ADD CONSTRAINT "Question_chapterId_fkey" FOREIGN KEY ("chapterId") REFERENCES "Chapter"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Choice" ADD CONSTRAINT "Choice_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExamSet" ADD CONSTRAINT "ExamSet_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ExamSetQuestion" ADD CONSTRAINT "ExamSetQuestion_examSetId_fkey" FOREIGN KEY ("examSetId") REFERENCES "ExamSet"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExamSetQuestion" ADD CONSTRAINT "ExamSetQuestion_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
